This section contains the contents of the repository's files.import AsyncStorage from '@react-native-async-storage/async-storage';
import { notifyCacheChange } from '../sync/cacheEvents';

/** Per-account, per-device organization; server read receipts remain monotonic. */
export type ChatListPreferences = {
  pinned: string[];
  ignored: string[];
  unread: string[];
  deleted: string[];
};
export type ChatListPreference = keyof ChatListPreferences;
const STORAGE_KEY = 'dg.chatListPreferences';
let writes: Promise<unknown> = Promise.resolve();

function normalize(value: unknown): ChatListPreferences {
  const record = value && typeof value === 'object' ? value as Record<string, unknown> : {};
  const ids = (key: ChatListPreference): string[] => Array.isArray(record[key])
    ? record[key].filter((id): id is string => typeof id === 'string') : [];
  return { pinned: ids('pinned'), ignored: ids('ignored'), unread: ids('unread'), deleted: ids('deleted') };
}

async function readAll(): Promise<Record<string, unknown>> {
  const value = await AsyncStorage.getItem(STORAGE_KEY);
  if (!value) return {};
  try {
    const parsed: unknown = JSON.parse(value);
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed as Record<string, unknown> : {};
  } catch {
    return {};
  }
}

export async function loadChatListPreferences(userId: string): Promise<ChatListPreferences> {
  await writes;
  return normalize((await readAll())[userId]);
}

/** Serialize read/modify/write so actions from mounted screens cannot overwrite each other. */
export function updateChatListPreferences(
  userId: string,
  chatId: string,
  patch: Partial<Record<ChatListPreference, boolean>>,
): Promise<ChatListPreferences> {
  const operation = writes.then(async () => {
    const all = await readAll();
    const current = normalize(all[userId]);
    let changed = false;
    for (const key of Object.keys(patch) as ChatListPreference[]) {
      const ids = new Set(current[key]);
      if (ids.has(chatId) === patch[key]) continue;
      if (patch[key]) ids.add(chatId);
      else ids.delete(chatId);
      current[key] = [...ids];
      changed = true;
    }
    if (changed) {
      all[userId] = current;
      await AsyncStorage.setItem(STORAGE_KEY, JSON.stringify(all));
      notifyCacheChange();
    }
    return current;
  });
  writes = operation.catch(() => {});
  return operation;
}

export function setChatListPreference(userId: string, chatId: string, preference: ChatListPreference, enabled: boolean) {
  return updateChatListPreferences(userId, chatId, { [preference]: enabled });
}/**
 * Cache reads for AND-12 (M2-07, D-44, D-91).
 *
 * Chat info renders from the synced local cache, so opening it does not depend on the network. The
 * rows are stored as the server JSON (6.4); a malformed payload is skipped rather than thrown.
 */
import type { SQLiteDatabase } from 'expo-sqlite';
import type { ChatMemberRow, ChatRow, ProfileRow } from '@dologram/shared';

export type ChatInfoSource = {
  chat: ChatRow | null;
  members: ChatMemberRow[];
  profiles: ProfileRow[];
};

function parsePayload<T>(payload: string | null): T | null {
  if (payload === null) return null;
  try {
    const parsed: unknown = JSON.parse(payload);
    return typeof parsed === 'object' && parsed !== null ? (parsed as T) : null;
  } catch {
    return null;
  }
}

export async function loadChatInfoSource(
  db: SQLiteDatabase,
  chatId: string,
): Promise<ChatInfoSource> {
  const chatRow = await db.getFirstAsync<{ payload: string }>(
    'SELECT payload FROM cache_chats WHERE chat_id = ?',
    [chatId],
  );
  const chat = parsePayload<ChatRow>(chatRow?.payload ?? null);

  const memberRows = await db.getAllAsync<{ payload: string }>(
    'SELECT payload FROM cache_chat_members WHERE chat_id = ?',
    [chatId],
  );
  const members: ChatMemberRow[] = [];
  for (const row of memberRows) {
    const member = parsePayload<ChatMemberRow>(row.payload);
    if (member) members.push(member);
  }

  const profiles: ProfileRow[] = [];
  if (members.length > 0) {
    const placeholders = members.map(() => '?').join(', ');
    const profileRows = await db.getAllAsync<{ payload: string }>(
      `SELECT payload FROM cache_profiles WHERE user_id IN (${placeholders})`,
      members.map((member) => member.user_id),
    );
    for (const row of profileRows) {
      const profile = parsePayload<ProfileRow>(row.payload);
      if (profile) profiles.push(profile);
    }
  }

  return { chat, members, profiles };
}

export type CachedContactRow = { user_id: string; display_name: string | null };

/**
 * Every other member of every cached chat: the people the caller already shares a chat with, which
 * is exactly who D-70 lets the caller put into a group.
 */
export async function loadCachedContacts(db: SQLiteDatabase, userId: string): Promise<CachedContactRow[]> {
  return db.getAllAsync<CachedContactRow>(
    `SELECT DISTINCT m.user_id AS user_id, p.display_name AS display_name
       FROM cache_chat_members m
       LEFT JOIN cache_profiles p ON p.user_id = m.user_id
      WHERE m.user_id <> ?`,
    [userId],
  );
}import AsyncStorage from '@react-native-async-storage/async-storage';

export type ChatThemeName = 'default' | 'ocean' | 'mint' | 'sunset' | 'violet';

export type ChatPreferences = {
  nickname: string;
  theme: ChatThemeName;
  emoji: string;
  notifications: boolean;
  sounds: boolean;
  blocked: boolean;
};

export const CHAT_THEME_OPTIONS: readonly {
  id: ChatThemeName;
  label: string;
  color: string;
}[] = [
  { id: 'default', label: 'Default', color: '#EDE8D0' },
  { id: 'ocean', label: 'Ocean', color: '#168AAD' },
  { id: 'mint', label: 'Mint', color: '#2A9D8F' },
  { id: 'sunset', label: 'Sunset', color: '#E76F51' },
  { id: 'violet', label: 'Violet', color: '#9B5DE5' },
];

export const CHAT_EMOJI_OPTIONS = ['👍', '❤️', '😂', '😮', '😢', '😡', '🔥', '✨'] as const;

export const DEFAULT_CHAT_PREFERENCES: ChatPreferences = {
  nickname: '',
  theme: 'default',
  emoji: '👍',
  notifications: true,
  sounds: true,
  blocked: false,
};

export const PINNED_MESSAGES_KEY = 'dg.pinnedMessages';

function storageKey(userId: string, chatId: string): string {
  return `dg.chatPreferences:${userId}:${chatId}`;
}

function isTheme(value: unknown): value is ChatThemeName {
  return CHAT_THEME_OPTIONS.some((option) => option.id === value);
}

function parsePreferences(value: string | null): ChatPreferences {
  if (!value) return DEFAULT_CHAT_PREFERENCES;
  try {
    const parsed: unknown = JSON.parse(value);
    if (typeof parsed !== 'object' || parsed === null) return DEFAULT_CHAT_PREFERENCES;
    const row = parsed as Partial<ChatPreferences>;
    return {
      nickname: typeof row.nickname === 'string' ? row.nickname : DEFAULT_CHAT_PREFERENCES.nickname,
      theme: isTheme(row.theme) ? row.theme : DEFAULT_CHAT_PREFERENCES.theme,
      emoji: typeof row.emoji === 'string' && row.emoji.length > 0 ? row.emoji : DEFAULT_CHAT_PREFERENCES.emoji,
      notifications: typeof row.notifications === 'boolean' ? row.notifications : DEFAULT_CHAT_PREFERENCES.notifications,
      sounds: typeof row.sounds === 'boolean' ? row.sounds : DEFAULT_CHAT_PREFERENCES.sounds,
      blocked: typeof row.blocked === 'boolean' ? row.blocked : DEFAULT_CHAT_PREFERENCES.blocked,
    };
  } catch {
    return DEFAULT_CHAT_PREFERENCES;
  }
}

export async function loadChatPreferences(userId: string, chatId: string): Promise<ChatPreferences> {
  return parsePreferences(await AsyncStorage.getItem(storageKey(userId, chatId)));
}

export async function saveChatPreferences(
  userId: string,
  chatId: string,
  preferences: ChatPreferences,
): Promise<void> {
  await AsyncStorage.setItem(storageKey(userId, chatId), JSON.stringify(preferences));
}

const preferenceWrites = new Map<string, Promise<unknown>>();
const preferenceListeners = new Map<string, Set<() => void>>();

function notifyPreferenceChange(userId: string, chatId: string): void {
  preferenceListeners.get(storageKey(userId, chatId))?.forEach((listener) => listener());
}

export function subscribeChatPreferenceChanges(userId: string, chatId: string, listener: () => void): () => void {
  const key = storageKey(userId, chatId);
  const listeners = preferenceListeners.get(key) ?? new Set<() => void>();
  listeners.add(listener);
  preferenceListeners.set(key, listeners);
  return () => {
    listeners.delete(listener);
    if (listeners.size === 0) preferenceListeners.delete(key);
  };
}

export async function updateChatPreferences(
  userId: string,
  chatId: string,
  patch: Partial<ChatPreferences>,
): Promise<ChatPreferences> {
  const key = storageKey(userId, chatId);
  const operation = (preferenceWrites.get(key) ?? Promise.resolve()).catch(() => undefined).then(async () => {
    const next = { ...parsePreferences(await AsyncStorage.getItem(key)), ...patch };
    await saveChatPreferences(userId, chatId, next);
    notifyPreferenceChange(userId, chatId);
    return next;
  });
  preferenceWrites.set(key, operation);
  try { return await operation; }
  finally { if (preferenceWrites.get(key) === operation) preferenceWrites.delete(key); }
}

export async function clearChatPreferences(userId: string, chatId: string): Promise<void> {
  await AsyncStorage.removeItem(storageKey(userId, chatId));
  notifyPreferenceChange(userId, chatId);
}

export async function loadPinnedMessageIds(userId: string): Promise<Set<string>> {
  const value = await AsyncStorage.getItem(`${PINNED_MESSAGES_KEY}:${userId}`);
  if (!value) return new Set();
  try {
    const parsed: unknown = JSON.parse(value);
    return new Set(Array.isArray(parsed) ? parsed.filter((id): id is string => typeof id === 'string') : []);
  } catch {
    return new Set();
  }
}

export async function savePinnedMessageIds(userId: string, ids: Iterable<string>): Promise<void> {
  await AsyncStorage.setItem(`${PINNED_MESSAGES_KEY}:${userId}`, JSON.stringify([...ids]));
}/**
 * CMP-03: Search field — height 40, full radius, debounced filtering.
 * 12.5, D-95
 */
import React, { useEffect, useRef, useState } from 'react';
import {
  TextInput,
  View,
  Pressable,
  StyleSheet,
  type TextInputProps,
} from 'react-native';
import { useTheme } from '../theme/ThemeProvider';
import { textStyle } from '../theme/typography';
import { Icon } from './Icon';

export interface SearchFieldProps extends Omit<TextInputProps, 'onChangeText'> {
  /** Called ~150 ms after the user stops typing. */
  onSearch: (query: string) => void;
  debounceMs?: number;
  inputRef?: React.Ref<TextInput>;
}

export function SearchField({
  onSearch,
  debounceMs = 150,
  placeholder = 'Search',
  inputRef,
  ...inputProps
}: SearchFieldProps) {
  const theme = useTheme();
  const c = theme.colors;
  const [value, setValue] = useState('');
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    return () => {
      if (timerRef.current) clearTimeout(timerRef.current);
    };
  }, []);

  const handleChange = (text: string) => {
    setValue(text);
    if (timerRef.current) clearTimeout(timerRef.current);
    if (debounceMs === 0) onSearch(text);
    else timerRef.current = setTimeout(() => onSearch(text), debounceMs);
  };

  const handleClear = () => {
    setValue('');
    if (timerRef.current) clearTimeout(timerRef.current);
    onSearch('');
  };

  return (
    <View
      style={[
        styles.container,
        {
          height: 40,
          borderRadius: theme.radius.full,
          backgroundColor: c.bg.surface,
          paddingHorizontal: theme.space[3],
        },
      ]}
    >
      <Icon name="action.search" size="sm" color={c.text.muted} />

      <TextInput
        ref={inputRef}
        style={[
          styles.input,
          { ...textStyle(theme.typeTokens.bodyMd), color: c.text.primary },
        ]}
        value={value}
        onChangeText={handleChange}
        placeholder={placeholder}
        placeholderTextColor={c.text.muted}
        returnKeyType="search"
        clearButtonMode="never"
        accessibilityRole="search"
        {...inputProps}
      />

      {value.length > 0 ? (
        <Pressable
          onPress={handleClear}
          accessibilityLabel="Clear search"
          accessibilityRole="button"
          style={styles.clearButton}
          hitSlop={8}
        >
          <Icon name="nav.close" size="sm" color={c.text.muted} />
        </Pressable>
      ) : null}
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 8,
  },
  input: { flex: 1 },
  clearButton: { padding: 2 },
});/** Queue change notifications used by the chat screen to repaint LS-2 status captions. */
const listeners = new Set<() => void>();

export function subscribeQueueChange(listener: () => void): () => void {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

export function notifyQueueChange(): void {
  for (const listener of listeners) listener();
}

export type ForwardOutcome = { userId: string; messageId: string; status: 'sent' | 'failed' };
const outcomeListeners = new Set<(outcome: ForwardOutcome) => void>();
export function subscribeForwardOutcome(listener: (outcome: ForwardOutcome) => void): () => void {
  outcomeListeners.add(listener);
  return () => { outcomeListeners.delete(listener); };
}
export function notifyForwardOutcome(outcome: ForwardOutcome): void {
  for (const listener of outcomeListeners) listener(outcome);
}import { DatabaseSync } from 'node:sqlite';
import type { SQLiteDatabase } from 'expo-sqlite';
import { normalizeSearch, searchCachedMessages } from '../query';

let sqlite: DatabaseSync;
let db: SQLiteDatabase;

beforeEach(() => {
  sqlite = new DatabaseSync(':memory:');
  sqlite.exec(`
    CREATE TABLE cache_messages (
      message_id TEXT PRIMARY KEY, chat_id TEXT, sender_id TEXT, seq INTEGER,
      created_at TEXT, deleted_at TEXT, payload TEXT
    );
    CREATE TABLE cache_chat_members (chat_id TEXT, user_id TEXT, nickname TEXT);
    CREATE TABLE cache_profiles (user_id TEXT, display_name TEXT);
    CREATE TABLE cache_message_media (message_id TEXT, payload TEXT);
    INSERT INTO cache_chat_members VALUES ('chat', 'me', NULL), ('chat', 'other', 'José');
  `);
  db = {
    getAllAsync: async (sql: string, params: string[]) => sqlite.prepare(sql).all(...params),
  } as unknown as SQLiteDatabase;
});

afterEach(() => sqlite.close());

function addMessage(id: string, content: string, options: {
  chatId?: string; senderId?: string; deleted?: boolean; seq?: number;
} = {}) {
  sqlite.prepare('INSERT INTO cache_messages VALUES (?, ?, ?, ?, ?, ?, ?)').run(
    id, options.chatId ?? 'chat', options.senderId ?? 'me', options.seq ?? 1,
    '2026-11-11T00:00:00Z', options.deleted ? '2026-11-11T01:00:00Z' : null,
    JSON.stringify({ content }),
  );
}

function search(query: string, cursor: Parameters<typeof searchCachedMessages>[4] = null) {
  return searchCachedMessages(db, 'me', '["chat"]', normalizeSearch(query), cursor, new AbortController().signal);
}

test('searches beyond the newest 200 rows and preserves tied-date pagination', async () => {
  for (let index = 0; index < 260; index++) {
    addMessage(String(index).padStart(3, '0'), index < 35 ? 'Needle' : 'Unrelated');
  }
  const first = await search('needle');
  expect(first.matches).toHaveLength(30);
  expect(first.matches[0].messageId).toBe('034');
  expect(first.next).toBeTruthy();
  const second = await search('needle', first.next);
  expect(second.matches).toHaveLength(5);
  expect(second.next).toBeNull();
  expect(new Set([...first.matches, ...second.matches].map((message) => message.messageId)).size).toBe(35);
});

test('excludes deleted messages, other accounts, and hidden conversations', async () => {
  addMessage('valid', 'needle');
  addMessage('deleted', 'needle', { deleted: true });
  addMessage('foreign', 'needle', { chatId: 'foreign' });
  sqlite.prepare('INSERT INTO cache_chat_members VALUES (?, ?, NULL)').run('foreign', 'someone-else');
  addMessage('hidden', 'needle', { chatId: 'hidden' });
  sqlite.prepare('INSERT INTO cache_chat_members VALUES (?, ?, NULL)').run('hidden', 'me');
  const result = await searchCachedMessages(db, 'me', '["chat","foreign"]', 'needle', null, new AbortController().signal);
  expect(result.matches.map((message) => message.messageId)).toEqual(['valid']);
});

test('normalizes Unicode and treats SQL metacharacters literally', async () => {
  addMessage('unicode', 'ＣＡＦÉ');
  addMessage('literal', "100%_ ' OR 1=1 --");
  expect((await search('café')).matches.map((message) => message.messageId)).toEqual(['unicode']);
  expect((await search("%_ ' OR 1=1 --")).matches.map((message) => message.messageId)).toEqual(['literal']);
});

test('matches sender nicknames and live attachment types', async () => {
  addMessage('nickname', 'hello', { senderId: 'other' });
  addMessage('file', '');
  addMessage('removed-file', '');
  sqlite.prepare('INSERT INTO cache_message_media VALUES (?, ?)').run('file', JSON.stringify({ media_type: 'file', deleted_at: null }));
  sqlite.prepare('INSERT INTO cache_message_media VALUES (?, ?)').run('removed-file', JSON.stringify({ media_type: 'file', deleted_at: '2026-11-11' }));
  expect((await search('josé')).matches.map((message) => message.messageId)).toEqual(['nickname']);
  const files = await search('file');
  expect(files.matches.map((message) => message.messageId)).toEqual(['file']);
  expect(files.matches[0].preview).toBe('File');
});

test('stops a cancelled search and returns no matches for an empty query', async () => {
  const controller = new AbortController();
  controller.abort();
  const getAll = jest.spyOn(db, 'getAllAsync');
  await searchCachedMessages(db, 'me', '["chat"]', 'hello', null, controller.signal);
  await search('');
  expect(getAll).not.toHaveBeenCalled();
