}/**
 * People the caller may put into a group (M2-07, AND-11, D-58, D-70).
 *
 * D-70 only allows adding a member who already shares a chat with the member adding them, so the
 * eligible set is exactly the other members of the chats the caller already belongs to. The rows
 * come from the local cache, which holds every synced `chat_members` row, so the list works with
 * the same data the chat list already uses.
 */
import { strings } from '../strings';

export type ContactCandidate = {
  userId: string;
  displayName: string;
};

/** One `chat_members` row joined with the cached profile name, as the SQL adapter returns it. */
export type CachedContactRow = {
  user_id: string;
  display_name: string | null;
};

/** Group members besides the creator (D-58: at most 100 members, so at most 99 added). */
export const maxSelectableMembers = 99;

function compareContacts(a: ContactCandidate, b: ContactCandidate): number {
  const left = a.displayName.toLowerCase();
  const right = b.displayName.toLowerCase();
  if (left < right) return -1;
  if (left > right) return 1;
  return a.userId < b.userId ? -1 : a.userId > b.userId ? 1 : 0;
}

/**
 * Distinct people who share a chat with the caller, without the caller and without `exclude`
 * (the members a chat already has). Sorted by display name, then user id.
 */
export function buildContactList(
  rows: readonly CachedContactRow[],
  userId: string,
  exclude: readonly string[] = [],
): ContactCandidate[] {
  const seen = new Set<string>(exclude);
  const contacts: ContactCandidate[] = [];

  for (const row of rows) {
    if (row.user_id === userId || seen.has(row.user_id)) continue;
    seen.add(row.user_id);
    contacts.push({
      userId: row.user_id,
      displayName: row.display_name ?? strings.chatList.unknownMember,
    });
  }

  return contacts.sort(compareContacts);
}

/**
 * Adds or removes one selected member, never exceeding `max` (D-58). A selection at the limit is
 * returned unchanged, so the screen can disable the further checkboxes.
 */
export function toggleContactSelection(
  selected: readonly string[],
  userId: string,
  max: number,
): readonly string[] {
  if (selected.includes(userId)) {
    return selected.filter((id) => id !== userId);
  }
  if (selected.length >= max) {
    return selected;
  }
  return [...selected, userId];
}/**
 * Direct-chat lookup (M2-07, D-70, C-8).
 *
 * chats.direct_key is unique on the server, so a second direct chat for the same pair is rejected.
 * Before inserting the three rows of a direct chat the client checks the synced local cache for an
 * existing chat with that member and opens it instead. Archived direct chats still count: D-70 says
 * a user hides an unwanted direct chat by archiving it, so archiving must not create a second one.
 * Saved Messages is a direct chat with only the caller as a member. A self-chat lookup therefore
 * resolves to that one-member chat instead of trying to create a two-member direct chat.
 */
import type { ChatListSourceRow } from '../chatList/types';

export type DirectChatLookup = {
  /** The signed-in user. */
  userId: string;
  /** The user the caller wants to message. */
  otherUserId: string;
};

/** The cached direct chat with `otherUserId`, or null when there is none. */
export function findDirectChatId(
  rows: readonly ChatListSourceRow[],
  lookup: DirectChatLookup,
): string | null {
  for (const row of rows) {
    if (row.chat.type !== 'direct') continue;
    if (lookup.otherUserId === lookup.userId) {
      if (row.chat.direct_key === lookup.userId) {
        return row.chat.chat_id;
      }
      continue;
    }
    if (row.otherMemberId === lookup.otherUserId) {
      return row.chat.chat_id;
    }
  }
  return null;
}/**
 * Queue contracts (M2-02, M2-03, LS-1 to LS-3, LS-7 to LS-9, D-06, D-10, D-27, D-77, D-93).
 *
 * The queue is the device-local record of 6.2: `temp_id` equals the `message_id` the row will use
 * (D-10), the payload is the insert it will send, and the status is the LS-2 set. Storage is a
 * platform adapter (expo-sqlite on mobile); everything here is platform-agnostic so the state
 * machine can be tested with a fake store, a fake clock and an injected fetch.
 */

/** LS-2. The two Low Signal labels are presentation refinements, not extra states (D-17). */
export type QueueStatus = 'queued' | 'sending' | 'sent' | 'failed';

import type { MediaType } from '../config';

/** A file copied into app-private storage before a message enters the durable queue (M3-02). */
export type QueuedAttachment = {
  media_id: string;
  media_type: MediaType;
  mime: string;
  size_bytes: number;
  local_uri: string;
  compressed: boolean;
};

/** The payload of an outgoing message, including its optional attachment work (M3-02). */
export type TextQueuePayload = {
  kind: 'text';
  chat_id: string;
  sender_id: string;
  content: string;
  reply_to: string | null;
  attachment_count: number;
  attachments: QueuedAttachment[];
  /** LS-6: the Force Low Signal Mode preference captured when the item was queued. */
  force_low_signal?: boolean;
  /** Device-only feedback intent, never included in the server message insert. */
  feedback?: 'forward';
};

export type QueuePayload = TextQueuePayload;

export type QueueItem = {
  /** Equals the message_id the delivered row uses (D-10). */
  temp_id: string;
  /** Copy of `payload.chat_id`, so per-chat strict order needs no JSON parse (D-93). */
  chat_id: string;
  payload: QueuePayload;
  status: QueueStatus;
  /** D-77: counts only attempts made while connected that failed with a network or server error. */
  retry_count: number;
  /** Epoch milliseconds; the worker attempts the item only once this has passed (D-77). */
  next_attempt_at: number;
  /**
   * True once an insert was attempted, so the row may exist on the server. Discard needs a
   * connection and a soft delete in that case, and works offline only while this is false (D-93).
   */
  row_may_exist: boolean;
  /** Whether the message row is absent, may exist, or is confirmed stored (D-93). */
  row_state: 'absent' | 'unknown' | 'stored';
  /** The kind of the last failure, for the item's caption in the chat (D-17, D-93). */
  last_error: 'network' | 'server' | 'rateLimited' | 'waitingWifi' | null;
  created_at: number;
};

/** The D-27 values the queue machine needs; `config.queue` satisfies it. */
export type QueueTiming = {
  timerMs: number;
  backoffBaseMs: number;
  backoffFactor: number;
  backoffCapMs: number;
  jitter: number;
  maxAttempts: number;
  maxUnsent: number;
};

/**
 * The storage contract every platform adapter implements (M2-02). The cache, cache rows and
 * `sync_state` belong to the same database (6.2) but are not reached here yet.
 */
export interface LocalQueueStore {
  /** Creates or upgrades the schema. Idempotent. */
  init(): Promise<void>;
  insert(item: QueueItem): Promise<void>;
  update(item: QueueItem): Promise<void>;
  get(tempId: string): Promise<QueueItem | null>;
  /** Every item that is not yet sent, oldest first (LS-7 counts queued, sending and failed). */
  listUnsent(): Promise<QueueItem[]>;
  countUnsent(): Promise<number>;
  /** LS-9: items left in `sending` at startup return to `queued`. */
  resetSending(): Promise<void>;
  /** D-77: a returning connection makes every queued item due at once without resetting counts. */
  makeAllDue(now: number): Promise<void>;
  delete(tempId: string): Promise<void>;
  /** Removes sent items; the chat shows delivered rows from the server from then on. */
  deleteSent(): Promise<void>;
  /** Returns sent items before cleanup so mobile can remove their private attachment copies. */
  listSent(): Promise<QueueItem[]>;
}

export type EnqueueResult =
  | { ok: true; item: QueueItem }
  | { ok: false; reason: 'queueFull' };{
